// Turns FMS's free-text {message} into the Meta request(s) to send.
// With WHATSAPP_TEMPLATE_NAME set: the approved utility template (docs/
// whatsapp-alerts.md, "Templates"), which Meta delivers even when the owner
// has not messaged the business number in the last 24 h. Free-form text is only
// delivered inside that window and is otherwise dropped after Meta has
// already said 200 (code 131047), so FMS thinks it was sent.
// Template values may not hold newlines/tabs or 4+ spaces, and the whole body
// must stay under 1024 characters: the first line becomes the title, the
// rest are joined into one line, and a long report goes out as parts "(1/3)"...
// With WHATSAPP_TEMPLATE_NAME empty: one free-form text, as before.
// Every request carries "<title> @ <time>" as biz_opaque_callback_data, which
// Meta hands back with the delivery status, so the status workflow
// (n8n/fms-whatsapp-status.json) can say which alert failed.
const TEMPLATE = '{{ $env.WHATSAPP_TEMPLATE_NAME }}'.trim();
const LANG = '{{ $env.WHATSAPP_TEMPLATE_LANG }}'.trim() || 'en';
const TO = '{{ $env.WHATSAPP_TO_NUMBER }}';
const MAX_TITLE = 60;
const MAX_BODY = 800; // + title + the template's own ~90 characters < 1024

const message = String(($input.first().json.body || {}).message || '').trim();
if (!message) throw new Error('No message in the request body');

const clean = (s) => s.replace(/\s+/g, ' ').trim();
const cut = (s, n) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);
let lines = message.split(/\r?\n/).map(clean).filter(Boolean);

// The factory relay puts "(Delayed: from …)" on top of a late alert, and the
// status workflow "(Missed: first sent …)" on a resent one: keep it, but take
// the title from the line after it.
const notes = [];
while (lines.length > 1 && /^\((Delayed|Missed)/i.test(lines[0])) notes.push(lines.shift());
let title = 'Notice';
if (lines.length > 1) title = lines.shift().replace(/\*/g, '').trim() || title;
lines = notes.concat(lines);

const sentAt = new Date().toLocaleString('en-PK', {
  timeZone: 'Asia/Karachi', day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit',
});
const tag = (t) => cut(`${t} @ ${sentAt}`, 200);

// Besides the request: title and resend (free-form text), saved in
// whatsapp_messages by "Remember sent" so a failed one can be sent again.
if (!TEMPLATE) {
  return [{ json: {
    payload: {
      messaging_product: 'whatsapp', to: TO, type: 'text', text: { body: message },
      biz_opaque_callback_data: tag(title),
    },
    title,
    resend: message,
  } }];
}

// Greedy split on line boundaries; a single over-long line is cut. A
// "• " line needs no " | " in front: the bullet already separates it.
const parts = [];
let cur = '';
for (let line of lines) {
  while (line.length > MAX_BODY) {
    if (cur) { parts.push(cur); cur = ''; }
    parts.push(line.slice(0, MAX_BODY));
    line = line.slice(MAX_BODY);
  }
  if (!line) continue;
  const next = cur ? `${cur}${line.startsWith('•') ? ' ' : ' | '}${line}` : line;
  if (next.length > MAX_BODY) { parts.push(cur); cur = line; } else cur = next;
}
if (cur) parts.push(cur);
if (parts.length === 0) parts.push('-');

return parts.map((body, i) => {
  const suffix = parts.length > 1 ? ` (${i + 1}/${parts.length})` : '';
  const partTitle = cut(title, MAX_TITLE - suffix.length) + suffix;
  return {
    json: {
      payload: {
        messaging_product: 'whatsapp',
        to: TO,
        type: 'template',
        template: {
          name: TEMPLATE,
          language: { code: LANG },
          components: [{
            type: 'body',
            parameters: [
              { type: 'text', text: partTitle },
              { type: 'text', text: body },
            ],
          }],
        },
        biz_opaque_callback_data: tag(partTitle),
      },
      title: partTitle,
      resend: `*${partTitle}*\n${body}`,
    },
  };
});
